import{_ as s,o as r,c as o,ak as a}from"./chunks/framework.BHDkgpnK.js";const p=JSON.parse('{"title":"KossJS TypeScript 接口封装使用文档","description":"","frontmatter":{},"headers":[],"relativePath":"zh/interface/ts/how-to-use.md","filePath":"zh/interface/ts/how-to-use.md","lastUpdated":1782214112000}'),t={name:"zh/interface/ts/how-to-use.md"};function n(i,e,l,d,c,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="kossjs-typescript-接口封装使用文档" tabindex="-1">KossJS TypeScript 接口封装使用文档 <a class="header-anchor" href="#kossjs-typescript-接口封装使用文档" aria-label="Permalink to “KossJS TypeScript 接口封装使用文档”">​</a></h1><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>本文档介绍 KossJS 的 TypeScript 接口封装 <em><strong>kossjs_interface.ts</strong></em>。</p></div><h2 id="_0-安装说明" tabindex="-1">0. 安装说明 <a class="header-anchor" href="#_0-安装说明" aria-label="Permalink to “0. 安装说明”">​</a></h2><h3 id="_0-1-系统要求" tabindex="-1">0.1 系统要求 <a class="header-anchor" href="#_0-1-系统要求" aria-label="Permalink to “0.1 系统要求”">​</a></h3><ol><li>Node.js 18 及以上版本</li><li>KossJS 动态库文件： <ul><li>Windows 平台：<em><strong>kossjs.dll</strong></em></li><li>macOS 平台：<em><strong>libkossjs.dylib</strong></em></li><li>Linux 平台：<em><strong>libkossjs.so</strong></em></li></ul></li><li>koffi（Node.js FFI 库）</li></ol><h3 id="_0-2-安装步骤" tabindex="-1">0.2 安装步骤 <a class="header-anchor" href="#_0-2-安装步骤" aria-label="Permalink to “0.2 安装步骤”">​</a></h3><ol><li>将动态库文件放置在项目目录中</li><li>将 <em><strong>kossjs_interface.ts</strong></em> 复制到项目目录</li><li>安装 koffi： pm install koffi</li></ol><hr><h2 id="_1-模块概述" tabindex="-1">1. 模块概述 <a class="header-anchor" href="#_1-模块概述" aria-label="Permalink to “1. 模块概述”">​</a></h2><ul><li><strong>核心类</strong>：<em><strong>KossJS</strong></em></li><li><strong>依赖</strong>：<em><strong>koffi</strong></em>（Node.js FFI 库）</li><li><strong>功能</strong>： <ul><li>创建 JS 实例（支持模块加载、能力位控制、稳定模式）</li><li>执行 JavaScript 代码</li><li>全局变量注入</li><li>注册原生函数</li><li>Fetch API 调用</li><li>沙箱安全（审核掩码、审核回调、调试模式）</li><li>Worker 线程池</li></ul></li></ul><hr><h2 id="_2-kossjs-类" tabindex="-1">2. <em><strong>KossJS</strong></em> 类 <a class="header-anchor" href="#_2-kossjs-类" aria-label="Permalink to “2. KossJS 类”">​</a></h2><h3 id="_2-1-初始化" tabindex="-1">2.1 初始化 <a class="header-anchor" href="#_2-1-初始化" aria-label="Permalink to “2.1 初始化”">​</a></h3><p><code> ypescript const koss = new KossJS( libPath?: string, // 动态库路径，默认自动检测 withModules?: boolean, // 是否启用模块加载，默认 false rootDir?: string, // 模块解析根目录，默认当前目录 capabilities?: number, // 能力位掩码，默认 KOSS_CAP_ALL stable?: boolean // 稳定模式，默认 true ); </code></p><p><strong>示例</strong>：</p><p>` ypescript import { KossJS } from &#39;./kossjs_interface&#39;;</p><p>// 默认创建（stable=true，生产模式） const koss = new KossJS();</p><p>// 沙箱模式 const sandbox = new KossJS(undefined, false, undefined, KossJS.KOSS_CAP_SANDBOX);</p><p>// 开发模式（启用 FFI 和 Worker） const dev = new KossJS(undefined, false, undefined, KossJS.KOSS_CAP_ALL, false); `</p><h3 id="_2-2-实例属性" tabindex="-1">2.2 实例属性 <a class="header-anchor" href="#_2-2-实例属性" aria-label="Permalink to “2.2 实例属性”">​</a></h3><h4 id="isstable-boolean" tabindex="-1"><em><strong>isStable(): boolean</strong></em> <a class="header-anchor" href="#isstable-boolean" aria-label="Permalink to “isStable(): boolean”">​</a></h4><p>查询实例是否处于稳定模式。</p><p><code> ypescript const koss = new KossJS(); console.log(koss.isStable()); // true </code></p><h4 id="getcapabilities-number" tabindex="-1"><em><strong>getCapabilities(): number</strong></em> <a class="header-anchor" href="#getcapabilities-number" aria-label="Permalink to “getCapabilities(): number”">​</a></h4><p>查询当前实例的能力位掩码。</p><p><code> ypescript const koss = new KossJS(); const caps = koss.getCapabilities(); console.log(Capabilities: 0x); </code></p><h3 id="_2-3-执行代码" tabindex="-1">2.3 执行代码 <a class="header-anchor" href="#_2-3-执行代码" aria-label="Permalink to “2.3 执行代码”">​</a></h3><h4 id="eval-code-string-any" tabindex="-1"><em><strong>eval(code: string): any</strong></em> <a class="header-anchor" href="#eval-code-string-any" aria-label="Permalink to “eval(code: string): any”">​</a></h4><p>执行 JavaScript 代码并返回结果。</p><p><code> ypescript const result = koss.eval(&quot;1 + 2&quot;); console.log(result); // 输出: 3 </code></p><h4 id="runasync-code-string-timeoutms-number-string" tabindex="-1"><em><strong>runAsync(code: string, timeoutMs?: number): string</strong></em> <a class="header-anchor" href="#runasync-code-string-timeoutms-number-string" aria-label="Permalink to “runAsync(code: string, timeoutMs?: number): string”">​</a></h4><p>执行异步代码并驱动事件循环直到 Promise 完成。</p><p><code> ypescript const result = koss.runAsync( (async () =&gt; { const r = await fetch(&quot;https://api.github.com/users/github&quot;); const d = await r.json(); return d.login; })(); , 30000); </code></p><h4 id="tick-boolean" tabindex="-1"><em><strong>tick(): boolean</strong></em> <a class="header-anchor" href="#tick-boolean" aria-label="Permalink to “tick(): boolean”">​</a></h4><p>运行事件循环单次迭代。</p><h4 id="runfile-path-string-string" tabindex="-1"><em><strong>runFile(path: string): string</strong></em> <a class="header-anchor" href="#runfile-path-string-string" aria-label="Permalink to “runFile(path: string): string”">​</a></h4><p>执行 JavaScript 文件。</p><h4 id="runmodule-path-string-string" tabindex="-1"><em><strong>runModule(path: string): string</strong></em> <a class="header-anchor" href="#runmodule-path-string-string" aria-label="Permalink to “runModule(path: string): string”">​</a></h4><p>以 ES Module 方式执行 JavaScript 文件。</p><h4 id="runstring-code-string-string" tabindex="-1"><em><strong>runString(code: string): string</strong></em> <a class="header-anchor" href="#runstring-code-string-string" aria-label="Permalink to “runString(code: string): string”">​</a></h4><p>执行 JavaScript 代码字符串。</p><h4 id="runmodulestring-code-string-string" tabindex="-1"><em><strong>runModuleString(code: string): string</strong></em> <a class="header-anchor" href="#runmodulestring-code-string-string" aria-label="Permalink to “runModuleString(code: string): string”">​</a></h4><p>以 ES Module 方式执行代码字符串。</p><h3 id="_2-4-全局变量" tabindex="-1">2.4 全局变量 <a class="header-anchor" href="#_2-4-全局变量" aria-label="Permalink to “2.4 全局变量”">​</a></h3><h4 id="setglobal-name-string-value-any-void" tabindex="-1"><em><strong>setGlobal(name: string, value: any): void</strong></em> <a class="header-anchor" href="#setglobal-name-string-value-any-void" aria-label="Permalink to “setGlobal(name: string, value: any): void”">​</a></h4><p>设置全局变量。</p><p><code> ypescript koss.setGlobal(&quot;myVar&quot;, &quot;Hello&quot;); koss.setGlobal(&quot;count&quot;, 100); koss.setGlobal(&quot;isReady&quot;, true); koss.setGlobal(&quot;config&quot;, { debug: true, port: 8080 }); </code></p><h3 id="_2-5-原生函数-类注册" tabindex="-1">2.5 原生函数 / 类注册 <a class="header-anchor" href="#_2-5-原生函数-类注册" aria-label="Permalink to “2.5 原生函数 / 类注册”">​</a></h3><h4 id="registerfunction-name-string-func-function-void" tabindex="-1"><em><strong>registerFunction(name: string, func: Function): void</strong></em> <a class="header-anchor" href="#registerfunction-name-string-func-function-void" aria-label="Permalink to “registerFunction(name: string, func: Function): void”">​</a></h4><p>注册可从 JS 调用的原生函数。</p><p><code> ypescript koss.registerFunction(&quot;add&quot;, (a: string, b: string) =&gt; { return String(Number(a) + Number(b)); }); const result = koss.eval(&quot;add(10, 20)&quot;); console.log(result); // 输出: 30 </code></p><h4 id="registerclass-classname-string-methods-record-string-function-void" tabindex="-1"><em><strong>registerClass(className: string, methods: Record&lt;string, Function&gt;): void</strong></em> <a class="header-anchor" href="#registerclass-classname-string-methods-record-string-function-void" aria-label="Permalink to “registerClass(className: string, methods: Record&lt;string, Function&gt;): void”">​</a></h4><p>注册支持 ew 关键字的 JS 类。</p><h3 id="_2-6-沙箱安全" tabindex="-1">2.6 沙箱安全 <a class="header-anchor" href="#_2-6-沙箱安全" aria-label="Permalink to “2.6 沙箱安全”">​</a></h3><h4 id="setauditmask-mask-number-void" tabindex="-1"><em><strong>setAuditMask(mask: number): void</strong></em> <a class="header-anchor" href="#setauditmask-mask-number-void" aria-label="Permalink to “setAuditMask(mask: number): void”">​</a></h4><p>设置审核掩码。</p><p><code> ypescript koss.setAuditMask(KossJS.FS_READ | KossJS.NET_FETCH); </code></p><h4 id="getauditmask-number" tabindex="-1"><em><strong>getAuditMask(): number</strong></em> <a class="header-anchor" href="#getauditmask-number" aria-label="Permalink to “getAuditMask(): number”">​</a></h4><p>获取当前审核掩码。</p><h4 id="checksandbox-callback-function-null-void" tabindex="-1"><em><strong>checkSandbox(callback: Function | null): void</strong></em> <a class="header-anchor" href="#checksandbox-callback-function-null-void" aria-label="Permalink to “checkSandbox(callback: Function | null): void”">​</a></h4><p>注册或清除审核回调。</p><p>` ypescript koss.checkSandbox((target: string, args: string[], pwd: string | null) =&gt; { if (target === &#39;fs.readFile&#39;) { return args[0].startsWith(&#39;/tmp/sandbox/&#39;); } return true; });</p><p>// 清除回调 koss.checkSandbox(null); `</p><h4 id="enableauditdebug-enable-boolean-void" tabindex="-1"><em><strong>enableAuditDebug(enable: boolean): void</strong></em> <a class="header-anchor" href="#enableauditdebug-enable-boolean-void" aria-label="Permalink to “enableAuditDebug(enable: boolean): void”">​</a></h4><p>启用/禁用审核调试模式。</p><p><code> ypescript koss.enableAuditDebug(true); // 开启 koss.enableAuditDebug(false); // 关闭 </code></p><h3 id="_2-7-worker-线程池" tabindex="-1">2.7 Worker 线程池 <a class="header-anchor" href="#_2-7-worker-线程池" aria-label="Permalink to “2.7 Worker 线程池”">​</a></h3><h4 id="createworkerpool-size-number-string" tabindex="-1"><em><strong>createWorkerPool(size: number): string</strong></em> <a class="header-anchor" href="#createworkerpool-size-number-string" aria-label="Permalink to “createWorkerPool(size: number): string”">​</a></h4><p>创建指定大小的 Worker 线程池（最大 64）。</p><h4 id="workerexecute-workerid-number-code-string-string" tabindex="-1"><em><strong>workerExecute(workerId: number, code: string): string</strong></em> <a class="header-anchor" href="#workerexecute-workerid-number-code-string-string" aria-label="Permalink to “workerExecute(workerId: number, code: string): string”">​</a></h4><p>在指定 Worker 上执行 JavaScript 代码。</p><h4 id="workerpostmessage-workerid-number-data-string-string" tabindex="-1"><em><strong>workerPostMessage(workerId: number, data: string): string</strong></em> <a class="header-anchor" href="#workerpostmessage-workerid-number-data-string-string" aria-label="Permalink to “workerPostMessage(workerId: number, data: string): string”">​</a></h4><p>向指定 Worker 发送 JSON 消息。</p><h4 id="workertryrecv-string-null" tabindex="-1"><em><strong>workerTryRecv(): string | null</strong></em> <a class="header-anchor" href="#workertryrecv-string-null" aria-label="Permalink to “workerTryRecv(): string | null”">​</a></h4><p>非阻塞收取 Worker 消息/执行结果。</p><h4 id="workerterminate-workerid-number-string" tabindex="-1"><em><strong>workerTerminate(workerId: number): string</strong></em> <a class="header-anchor" href="#workerterminate-workerid-number-string" aria-label="Permalink to “workerTerminate(workerId: number): string”">​</a></h4><p>终止指定 Worker 线程。</p><h4 id="workershutdown-string" tabindex="-1"><em><strong>workerShutdown(): string</strong></em> <a class="header-anchor" href="#workershutdown-string" aria-label="Permalink to “workerShutdown(): string”">​</a></h4><p>关闭全部 Worker 线程池。</p><p><code> ypescript const koss = new KossJS(undefined, false, undefined, KossJS.KOSS_CAP_ALL, false); koss.createWorkerPool(2); koss.workerExecute(0, &quot;1 + 1&quot;); const msg = koss.workerTryRecv(); console.log(msg); koss.workerShutdown(); </code></p><h3 id="_2-8-资源管理" tabindex="-1">2.8 资源管理 <a class="header-anchor" href="#_2-8-资源管理" aria-label="Permalink to “2.8 资源管理”">​</a></h3><h4 id="destroy-void" tabindex="-1"><em><strong>destroy(): void</strong></em> <a class="header-anchor" href="#destroy-void" aria-label="Permalink to “destroy(): void”">​</a></h4><p>销毁 JS 实例并释放内存。</p><p><code> ypescript koss.destroy(); </code></p><h3 id="_2-9-其他方法" tabindex="-1">2.9 其他方法 <a class="header-anchor" href="#_2-9-其他方法" aria-label="Permalink to “2.9 其他方法”">​</a></h3><h4 id="version-string" tabindex="-1"><em><strong>version(): string</strong></em> <a class="header-anchor" href="#version-string" aria-label="Permalink to “version(): string”">​</a></h4><p>获取 KossJS 版本。</p><p><code> ypescript console.log(koss.version()); // 输出: 0.1.0-dev.8 </code></p><hr><h2 id="_3-使用示例" tabindex="-1">3. 使用示例 <a class="header-anchor" href="#_3-使用示例" aria-label="Permalink to “3. 使用示例”">​</a></h2><h3 id="_3-1-基本用法" tabindex="-1">3.1 基本用法 <a class="header-anchor" href="#_3-1-基本用法" aria-label="Permalink to “3.1 基本用法”">​</a></h3><p>` ypescript import { KossJS } from &#39;./kossjs_interface&#39;;</p><p>const koss = new KossJS();</p><p>// 基本计算 const result = koss.eval(&quot;1 + 2 * 3&quot;); console.log(result); // 输出: 7</p><p>// 对象操作 const name = koss.eval( const person = { name: &quot;John&quot;, age: 30 }; person.name; ); console.log(name); // 输出: John</p><p>koss.destroy(); `</p><h3 id="_3-2-使用沙箱能力位" tabindex="-1">3.2 使用沙箱能力位 <a class="header-anchor" href="#_3-2-使用沙箱能力位" aria-label="Permalink to “3.2 使用沙箱能力位”">​</a></h3><p>` ypescript import { KossJS } from &#39;./kossjs_interface&#39;;</p><p>// 沙箱模式 const sandbox = new KossJS(undefined, false, undefined, KossJS.KOSS_CAP_SANDBOX); const result = sandbox.eval(&quot;1 + 1&quot;); console.log(result); // 正常工作 sandbox.destroy(); `</p><h3 id="_3-3-使用审核回调" tabindex="-1">3.3 使用审核回调 <a class="header-anchor" href="#_3-3-使用审核回调" aria-label="Permalink to “3.3 使用审核回调”">​</a></h3><p>` ypescript import { KossJS, JsError } from &#39;./kossjs_interface&#39;;</p><p>const koss = new KossJS(undefined, false, undefined, KossJS.KOSS_CAP_ALL_FS); koss.setAuditMask(KossJS.FS_READ);</p><p>koss.checkSandbox((target: string, args: string[]) =&gt; { if (target === &#39;fs.readFile&#39;) { return args[0].startsWith(&#39;/tmp/sandbox/&#39;); } return true; });</p><p>try { koss.eval(&quot;require(&#39;fs&#39;).readFileSync(&#39;/etc/passwd&#39;)&quot;); } catch (e) { if (e instanceof JsError) { console.log(Blocked: ); } }</p><p>koss.destroy(); `</p><hr><h2 id="_4-能力常量参考" tabindex="-1">4. 能力常量参考 <a class="header-anchor" href="#_4-能力常量参考" aria-label="Permalink to “4. 能力常量参考”">​</a></h2><p>` ypescript // 文件系统（6 个） KossJS.FS_READ = 1 &lt;&lt; 0; KossJS.FS_WRITE = 1 &lt;&lt; 1; KossJS.FS_DELETE = 1 &lt;&lt; 2; KossJS.FS_MKDIR = 1 &lt;&lt; 3; KossJS.FS_RENAME = 1 &lt;&lt; 4; KossJS.FS_CHMOD = 1 &lt;&lt; 5;</p><p>// 网络（5 个） KossJS.NET_TCP_CLIENT = 1 &lt;&lt; 6; KossJS.NET_TCP_SERVER = 1 &lt;&lt; 7; KossJS.NET_UDP = 1 &lt;&lt; 8; KossJS.NET_DNS = 1 &lt;&lt; 9; KossJS.NET_FETCH = 1 &lt;&lt; 10;</p><p>// 加密（4 个） KossJS.CRYPTO_HASH = 1 &lt;&lt; 11; KossJS.CRYPTO_HMAC = 1 &lt;&lt; 12; KossJS.CRYPTO_RANDOM = 1 &lt;&lt; 13; KossJS.CRYPTO_PBKDF2 = 1 &lt;&lt; 14;</p><p>// 内置 FFI（5 个） KossJS.FFI_OPEN = 1 &lt;&lt; 15; KossJS.FFI_CALL = 1 &lt;&lt; 16; KossJS.FFI_ALLOC = 1 &lt;&lt; 17; KossJS.FFI_CALLBACK = 1 &lt;&lt; 18; KossJS.FFI_STRUCT = 1 &lt;&lt; 19;</p><p>// 其他模块（8 个） KossJS.NATIVE_ADDON = 1 &lt;&lt; 20; KossJS.WASM = 1 &lt;&lt; 21; KossJS.SHARED_MEMORY = 1 &lt;&lt; 22; KossJS.HIGHRES_TIME = 1 &lt;&lt; 23; KossJS.SYSINFO = 1 &lt;&lt; 24; KossJS.MODULE_LOAD = 1 &lt;&lt; 25; KossJS.DYNAMIC_CODE = 1 &lt;&lt; 26; KossJS.DEBUG_CAP = 1 &lt;&lt; 27;</p><p>// 组合常量 KossJS.KOSS_CAP_SANDBOX = 0; KossJS.KOSS_CAP_ALL_FS = KossJS.FS_READ | KossJS.FS_WRITE | KossJS.FS_DELETE | KossJS.FS_MKDIR | KossJS.FS_RENAME | KossJS.FS_CHMOD; KossJS.KOSS_CAP_ALL_NET = KossJS.NET_TCP_CLIENT | KossJS.NET_TCP_SERVER | KossJS.NET_UDP | KossJS.NET_DNS | KossJS.NET_FETCH; KossJS.KOSS_CAP_ALL_CRYPTO = KossJS.CRYPTO_HASH | KossJS.CRYPTO_HMAC | KossJS.CRYPTO_RANDOM | KossJS.CRYPTO_PBKDF2; KossJS.KOSS_CAP_ALL_FFI = KossJS.FFI_OPEN | KossJS.FFI_CALL | KossJS.FFI_ALLOC | KossJS.FFI_CALLBACK | KossJS.FFI_STRUCT; KossJS.KOSS_CAP_ALL = 0xFFFFFFFF;</p><p>// 兼容别名 KossJS.KOSS_CAP_FS = KossJS.KOSS_CAP_ALL_FS; KossJS.KOSS_CAP_NET = KossJS.KOSS_CAP_ALL_NET; KossJS.KOSS_CAP_CRYPTO = KossJS.KOSS_CAP_ALL_CRYPTO; KossJS.KOSS_CAP_WORKER = 1 &lt;&lt; 3; KossJS.KOSS_CAP_EXTERNAL_LOADER = KossJS.MODULE_LOAD; `</p><hr><h2 id="_5-注意事项" tabindex="-1">5. 注意事项 <a class="header-anchor" href="#_5-注意事项" aria-label="Permalink to “5. 注意事项”">​</a></h2><ol><li><strong>koffi 依赖</strong>：TypeScript 接口依赖 koffi 库，需要先安装</li><li><strong>动态库路径</strong>：若自动检测失败，需显式传入正确路径</li><li><strong>异常处理</strong>：JavaScript 错误会抛出 <em><strong>JsError</strong></em> 异常</li><li><strong>稳定模式</strong>：生产环境使用默认 <em><strong>stable=true</strong></em>，开发/调试使用 <em><strong>stable=false</strong></em></li><li><strong>Worker 隔离</strong>：Worker 功能在 <em><strong>stable=true</strong></em> 时被禁用</li></ol><hr><p>如有问题，请提交 issue。</p>',119)])])}const u=s(t,[["render",n]]);export{p as __pageData,u as default};
